private final CopyOnWriteArrayList<Listener> listeners =
        new CopyOnWriteArrayList<>();

void add(Listener l) { listeners.add(l); }        // copies the array
void fire(Event e)   { for (Listener l : listeners) l.on(e); }  // snapshot

